prompt --application/shared_components/user_interface/templates/region/zoom_dial
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(338086419125614042)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TZoomDial #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TZoomDial-header">',
'    <span class="amc-TZoomDial-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'    <h2 class="amc-TZoomDial-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'    <div class="amc-TZoomDial-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    <div class="amc-TZoomDial-control">',
'      <div class="amc-TZoomDial-dial" role="group" aria-label="Content size">',
'        <span class="amc-TZoomDial-thumb" aria-hidden="true"></span>',
'        <button type="button" class="amc-TZoomDial-step" data-amc-level="1" aria-pressed="false" title="Compact"><span class="amc-TZoomDial-glyph" aria-hidden="true">A</span><span class="amc-TZoomDial-name">Compact</span></button>',
'        <button type="button" class="amc-TZoomDial-step" data-amc-level="2" aria-pressed="false" title="Cozy"><span class="amc-TZoomDial-glyph" aria-hidden="true">A</span><span class="amc-TZoomDial-name">Cozy</span></button>',
'        <button type="button" class="amc-TZoomDial-step" data-amc-level="3" aria-pressed="false" title="Comfortable"><span class="amc-TZoomDial-glyph" aria-hidden="true">A</span><span class="amc-TZoomDial-name">Comfortable</span></button>',
'        <button type="button" class="amc-TZoomDial-step" data-amc-level="4" aria-pressed="false" title="Large"><span class="amc-TZoomDial-glyph" aria-hidden="true">A</span><span class="amc-TZoomDial-name">Large</span></button>',
'      </div>',
'      <span class="amc-TZoomDial-readout" role="status" aria-live="polite"></span>',
'    </div>',
'  </header>',
'  <div class="amc-TZoomDial-body">',
'    <div class="amc-TZoomDial-zoom">#BODY##SUB_REGIONS#</div>',
'  </div>',
'  <footer class="amc-TZoomDial-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'</section>'))
,p_page_plug_template_name=>'AMC Zoom Dial'
,p_internal_name=>'AMC_TPL_ZOOM_DIAL'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-zoom-dial.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-zoom-dial.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Living region template (behaviour-aware). The header holds a size dial with four steps, Compact 87.5 percent, Cozy 100 percent, Comfortable 112.5 percent and Large 125 percent, as a group of real buttons with aria-pressed, plus a small readout of the current level and percentage that is announced politely when it changes. Arrow keys, Home and End move along the dial in reading direction. The level sets the CSS zoom property on an inner wrapper around the region body, so the native content is laid out again at that size: text wraps, report columns reflow and charts get a resize event to redraw. zoom is used rather than transform because it does not create a containing block, so date pickers, report menus and other fixed-position popups keep working, and the body is never clipped; wide content scrolls sideways. The choice is remembered in localStorage per application, page and region (key amc-tpl-zoom-dial:APP_ID:PAGE_ID:region static ID) and nothing leaves the browser; give the region a Static ID so the key survives changes. Picking the default level again is the way to reset. Browser support: CSS zoom works in Chromium-based browsers and Safari, and in Firefox from version 126; where it is not supported the dial is hidden and the content stays at 100 percent. Without JavaScript the default level from the template options still applies and the dial is hidden. Template options: Default Compact, Default Comfortable and Default Large set the starting level (Cozy when none is chosen); Hide readout keeps the level text for screen readers only; No body padding runs reports edge to edge. English UI strings to translate in the template: the group label Content size and the step names Compact, Cozy, Comfortable and Large, each used as button text for screen readers and as its title tooltip. Under reduced motion the dial thumb does not slide. JavaScript API: amcTplZoomDial.set(element, level 1 to 4) and amcTplZoomDial.get(element); the region fires a bubbling amczoomdial event after each change.'
);
end;
/
